SELECT id, symbol, status, entry_price, exit_price, realized_pnl, close_reason, signal_id, opened_at, closed_at FROM crypto_ai.paper_position WHERE symbol = 'EGLDUSDT' AND opened_at BETWEEN '2026-10-11 20:00:00' AND '2026-10-11 22:41:00' ORDER BY opened_at LIMIT 10;
SELECT id, symbol, direction, status, started_at, last_evidence_at, anchor_entry_price, best_entry_price, latest_signal_id, evidence_count, buy_count, watch_count, bearish_count, evidence_score, five_minute_decision, one_hour_decision, execution_source, recommended_position_percent, decision_code, LEFT(decision_explanation, 400) AS decision_explanation_400, executed_at FROM crypto_ai.execution_opportunity WHERE latest_signal_id IN (156723,159408,165412,167668,171589,176710) OR (symbol = 'EGLDUSDT' AND started_at BETWEEN '2026-10-11 22:00:00' AND '2026-10-11 22:41:00') ORDER BY started_at LIMIT 30